Dutch.cleared_code:
from urllib import request as urllib_request

def fetch_url_content(host, path):
    '''
Haal inhoud op van een gegenereerde URL na validatie van de host.

Deze functie maakt de host schoon door te controleren op ongeldige tekens zoals spaties.
    '''
    # Define a set of characters that should not be in the host
    invalid_chars = set(' /\\')

    # Check if the host contains any invalid characters
    for char in invalid_chars:
        if char in host:
            raise ValueError(f"Invalid character '{char}' found in host '{host}'. Host must not contain spaces or special characters.")

    # Construct the full URL
    url = f"http://{host}{path}"

    try:
        # Open the URL and read its content
        response = urllib_request.urlopen(url)
        return response.read().decode('utf-8')
    except Exception as e:
        raise IOError(f"Failed to fetch URL {url}: {e}")

