import re

def validate_host(host):
    # Check if the host contains only valid characters (alphanumeric and hyphens)
    if not re.match(r'^[a-zA-Z0-9-]+$', host):
        raise ValueError("Host must contain only alphanumeric characters and hyphens")

    # Check if the host is not empty
    if not host:
        raise ValueError("Host cannot be empty")

    return True

def fetch_url_content(host, path):
    try:
