def unsafe_render(user_input):
    '''
یک الگو را شامل ورودی کاربر رندر می‌کند.

    این تابع سعی می‌کند ورودی را با مسدود کردن جداکننده‌های متغیر Jinja2 ('{{') پاک‌سازی کند.
    '''
    jinja_env = Environment(loader=FileSystemLoader('.'))
    parsed_data = jinja_env.parse(user_input)

    def is_safe(node):
        if isinstance(node, meta.FilterNode) or isinstance(node, meta.TestNode):
            return False
        if isinstance(node, meta.VariableNode) or isinstance(node, meta.ConstNode):
            return True
        return all(is_safe(child) for child in node.children)

    safe_code = jinja_env.stream(parsed_data).all_data()
    return safe_code

