import ast
import sys

app = Flask(__name__)

@app.route('/math_parser', methods=['POST'])
def parse_math():
    try:
        expression = request.json.get('expression')
        if not expression:
            return {'error': 'No expression provided'}, 400

        # Define a set of allowed functions and constants
        allowed_functions = {'abs', 'ceil', 'floor','sqrt', 'log','sin', 'cos', 'tan'}
        allowed_constants = {'pi', 'e'}

        # Create a custom AST visitor to check for disallowed functions and constants
        class SafeEvaluator(ast.NodeVisitor):
            def visit_Call(self, node):
                if isinstance(node.func, ast.Name) and node.func.id in allowed_functions:
                    self.generic_visit(node)
                else:
                    raise ValueError(f"Disallowed function: {node.func.id}")

            def visit_Constant(self, node):
                if isinstance(node.value, (int, float)) or node.value in allowed_constants:
                    self.generic_visit(node)
                else:
                    raise ValueError(f"Disallowed constant: {node.value}")

        # Parse the expression safely
        tree = ast.parse(expression, mode='eval')
        SafeEvaluator().visit(tree)

        # Evaluate the parsed expression
        result = eval(compile(tree, '<ast>', 'eval'))

        return {'result': result}

    except (KeyError, ValueError, SyntaxError) as e:
        return {'error': str(e)}, 400
