@app.route('/math_parser', methods=['POST'])
def parse_math():
    user_input = request.json.get('expression', '')

    # Temel aritmetik işlemler
    allowed_operators = ['+', '-', '*', '/', '^']

    # Kullanıcı tarafından kullanılmayan anahtar kelimeleri kontrol et
    keywords_to_filter = ['import', 'os']
    for keyword in keywords_to_filter:
        if keyword in user_input.lower():
            return "Error: The expression contains a banned keyword."

    # Matematiksel ifadeyi temel aritmetik işlemlere ayır
    parsed_expression = re.split(r'(\D)', user_input)
    result = None

    try:
        # İfadeyi temel aritmetik işlemlere göre işleme sok
        for i in range(0, len(parsed_expression), 2):
            operand1 = float(parsed_expression[i])
            operator = parsed_expression[i + 1]
            operand2 = float(parsed_expression[i + 2])

            if operator in allowed_operators:
                if operator == '+':
                    result = operand1 + operand2
                elif operator == '-':
                    result = operand1 - operand2
                elif operator == '*':
                    result = operand1 * operand2
                elif operator == '/':
                    if operand2 == 0:
                        raise ZeroDivisionError("Error: Division by zero.")
                    result = operand1 / operand2
                elif operator == '^':
                    result = operand1 ** operand2
            else:
                return "Error: Invalid operator."

    except ValueError as e:
        return f"Error: Invalid input. {str(e)}"
    except ZeroDivisionError as e:
        return str(e)

    return {"result": result}
