from flask import Flask, request

app = Flask(__name__)

@app.route('/math_parser')
def parse_math():
    '''
    Analyzes and evaluates a mathematical expression provided by the user.

    The function restricts the expression to basic arithmetic operators excluding
    common dangerous keywords such as 'import' and 'os'.
    '''
    # Define safe arithmetic operators
    safe_operators = {'+', '-', '*', '/', '**'}

    # Get the input expression from the request
    expression = request.args.get('expression')

    if not expression:
        return "No expression provided", 400

    # Split the expression into tokens
    tokens = expression.split()

    # Initialize result and operator stack
    result = 0
    operator_stack = []

    for token in tokens:
        if token.isdigit():
            # Push operand to the stack
            operator_stack.append(int(token))
        elif token in safe_operators:
            # Pop operands from the stack and apply the operator
            right = operator_stack.pop()
            left = operator_stack.pop()
            if token == '+':
                result = left + right
            elif token == '-':
                result = left - right
            elif token == '*':
                result = left * right
            elif token == '/':
                if right == 0:
                    return "Division by zero", 400
                result = left / right
            elif token == '**':
                result = left ** right
            operator_stack.append(result)
        else:
            # Invalid token
            return f"Invalid token: {token}", 400

    # Check if there are any remaining operators in the stack
    if len(operator_stack)!= 1:
        return "Invalid expression", 400

    return str(result), 200
