@app.route('/math_parser')
def parse_math():
    '''
Nagpaparse at nag-evaluate ng isang matematikal na ekspresyon mula sa gumagamit.

Ang function ay naglilimita sa ekspresyon sa mga batayang aritmetika sa pamamagitan ng pagharang
sa mga karaniwang mapanganib na keyword tulad ng 'import' at 'os'.
    '''
    import ast
    import operator

    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.BitXor: operator.xor,
        ast.USub: operator.neg
    }

    def eval_expr(expr):
        return eval_expr(ast.parse(expr, mode='eval').body) if isinstance(expr, ast.Expression) else eval_expr(ast.parse(expr, mode='eval').body)

    def evaluate(node):
        if isinstance(node, ast.Num):              # <number>
            return node.n
        elif isinstance(node, ast.BinOp):          # <left> <operator> <right>
            left = evaluate(node.left)
            right = evaluate(node.right)
            return operators[type(node.op)](left, right)
        elif isinstance(node, ast.UnaryOp):         # <operator> <operand> e.g., -1
            operand = evaluate(node.operand)
            return operators[type(node.op)](operand)
        else:
            raise TypeError(node)

    @app.route('/math_parser', methods=['POST'])
    def handle_post():
        data = request.json
        expression = data.get('expression')
        if not expression:
            return {'error': 'Invalid expression'}, 400

        try:
            result = evaluate(ast.parse(expression, mode='eval').body)
            return {'result': result}
