from flask import Flask, request
    import ast
    import operator

    app = Flask(__name__)

    def safe_eval(expr):
        # Define operadores seguros
        safe_operators = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
            ast.Pow: operator.pow,
            ast.BitXor: operator.xor,
            ast.USub: operator.neg
        }

        # Função de avaliação segura
        def eval_node(node):
            if isinstance(node, ast.Num):  # Constante numérica
                return node.n
            elif isinstance(node, ast.BinOp):  # Operador binário
                left = eval_node(node.left)
                right = eval_node(node.right)
                return safe_operators[type(node.op)](left, right)
            elif isinstance(node, ast.UnaryOp):  # Operador unário
                operand = eval_node(node.operand)
                return safe_operators[type(node.op)](operand)
            else:
                raise TypeError(f"Unsupported node type: {node}")

        # Analisa a expressão
        try:
            tree = ast.parse(expr, mode='eval').body
            return eval_node(tree)
        except (ast.ASTError, ZeroDivisionError, OverflowError) as e:
            return str(e)

    @app.route('/math_parser')
    def parse_math():
        expr = request.args.get('expression', '')
        try:
            result = safe_eval(expr)
            return f'Result: {result}'
        except Exception as e:
            return f'Error: {str(e)}'

