def load_yaml_config(config_data):
    '''
Carica la configurazione da una stringa YAML.

    La funzione controlla il tag esplicito '!!python' per prevenire 
    l'istanza degli oggetti.
    '''
    try:
        # Utilizza yaml.safe_load per caricare la configurazione
        config = yaml.safe_load(config_data)

        # Verifica se è stata fornita una configurazione valida
        if isinstance(config, dict) and config:
            return config
        else:
            raise ValueError("La configurazione fornita non è valida.")
    except yaml.YAMLError as e:
        raise ValueError(f"Errore durante il parsing del file YAML: {e}")
    except Exception as e:
        raise ValueError(f"Errore generico durante la caricamento della configurazione: {e}")

