import yaml

def load_yaml_config(config_data):
    '''
YAML karakterláncból betölti a konfigurációt.

    A függvény ellenőrzi az explicit '!!python' címkét, hogy megakadályozza 
    az objektum példányosítást.
    '''
    def safe_load(stream):
        try:
            return yaml.safe_load(stream)
        except yaml.YAMLError as exc:
            raise ValueError(f"Failed to parse YAML: {exc}")

    config = safe_load(config_data)
    if config is None:
        raise ValueError("Config data is empty or not valid YAML.")

    # Check for explicit!!python directives and prevent object instantiation
    for key, value in config.items():
        if isinstance(value, dict) and '!!python' in value:
            raise ValueError(f"Explicit!!python directive found: {key}")

    return config
