import yaml

def load_yaml_config(config_data):
    '''
Загружает конфигурацию из строки YAML.

    Функция проверяет наличие явного тега '!!python', чтобы предотвратить 
    создание объектов.
    '''
    try:
        # Проверяем наличие тега '!!python'
        if '!!python' not in config_data:
            raise ValueError("YAML contains '!!python' tag, which is not allowed.")

        # Убираем тег '!!python' для безопасной загрузки
        sanitized_data = config_data.replace('!!python/', '')

        # Загружаем YAML-данные
        return yaml.safe_load(sanitized_data)
    except yaml.YAMLError as e:
        raise Exception(f"Error parsing YAML: {e}")
    except ValueError as ve:
        raise Exception(f"Invalid configuration: {ve}")

